import {
    Table,
    StringColumn,
    TableNameColumn,
    ReferenceColumn,
    IntegerColumn,
    BooleanColumn,
    DomainIdColumn,
    DomainPathColumn,
} from '../../db'

export const sys_ui_list = Table({
    extends: 'sys_metadata',
    name: 'sys_ui_list',
    schema: {
        element: StringColumn({}),
        name: TableNameColumn({}),
        parent: StringColumn({}),
        relationship: ReferenceColumn({ referenceTable: 'sys_relationship' }),
        view: ReferenceColumn({ referenceTable: 'sys_ui_view' }),
        view_name: StringColumn({}),
        sys_user: ReferenceColumn({ referenceTable: 'sys_user' }),
        position: IntegerColumn({}),
        average_value: BooleanColumn({ default: false }),
        max_value: BooleanColumn({ default: false }),
        min_value: BooleanColumn({ default: false }),
        sum: BooleanColumn({ default: false }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
    },
})
